  enterLoanInformation(
    requestid: number,
    name: string,
    loanamount: number,
    loanpurpose: string,
    income: number,
    phonenumber: number,
    postaladdress: string,
    zipcode: number,
    email: string,
    workreferences: string,
    creditreferences: string,
    checkingaccountnumber: number,
    securitynumber: number,
  ): boolean {
    /*Definition Start*/
    let existingLR: LoanRequest = l({
      logic: () =>
        getRepository(LoanRequest).find(
          (o: any) =>
            l({
              logic: () => o.RequestID === requestid,
              description: "o.RequestID=requestid",
            }).build().pass,
        ),
      description: "LoanRequest.allInstance()->any(o|o.RequestID=requestid)",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => true,
        description: "true",
      }).build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    let newLR: LoanRequest;
    return l({
      execute: () => (newLR = new LoanRequest()),
      description: "newLR.oclIsNew()",
    })
      .if({
        logic: () =>
          l({
            logic: () => StandardOPs.oclIsUndefined(existingLR),
            description: "existingLR.oclIsUndefined()",
          }),
        description: "existingLR.oclIsUndefined()",
        then: l({
          execute: () => getRepository(LoanRequest).push(newLR),
          description: "LoanRequest.allInstance()->includes(newLR)",
        })
          .and({
            execute: () => (newLR.RequestID = requestid),
            description: "newLR.RequestID=requestid",
          })
          .and({
            execute: () => (newLR.Name = name),
            description: "newLR.Name=name",
          })
          .and({
            execute: () => (newLR.LoanAmount = loanamount),
            description: "newLR.LoanAmount=loanamount",
          })
          .and({
            execute: () => (newLR.LoanPurpose = loanpurpose),
            description: "newLR.LoanPurpose=loanpurpose",
          })
          .and({
            execute: () => (newLR.Income = income),
            description: "newLR.Income=income",
          })
          .and({
            execute: () => (newLR.PhoneNumber = phonenumber),
            description: "newLR.PhoneNumber=phonenumber",
          })
          .and({
            execute: () => (newLR.PostalAddress = postaladdress),
            description: "newLR.PostalAddress=postaladdress",
          })
          .and({
            execute: () => (newLR.ZipCode = zipcode),
            description: "newLR.ZipCode=zipcode",
          })
          .and({
            execute: () => (newLR.Email = email),
            description: "newLR.Email=email",
          })
          .and({
            execute: () => (newLR.WorkReferences = workreferences),
            description: "newLR.WorkReferences=workreferences",
          })
          .and({
            execute: () => (newLR.CreditReferences = creditreferences),
            description: "newLR.CreditReferences=creditreferences",
          })
          .and({
            execute: () =>
              (newLR.CheckingAccountNumber = checkingaccountnumber),
            description: "newLR.CheckingAccountNumber=checkingaccountnumber",
          })
          .and({
            execute: () => (newLR.SecurityNumber = securitynumber),
            description: "newLR.SecurityNumber=securitynumber",
          })
          .and({
            execute: () => (newLR.Status = LoanRequestStatus.SUBMITTED),
            description: "newLR.Status=LoanRequestStatus::SUBMITTED",
          })
          .and({
            execute: () => (this.CurrentLoanRequest = newLR),
            description: "self.CurrentLoanRequest=newLR",
          }),
        else: l({
          execute: () => (this.CurrentLoanRequest = existingLR),
          description: "self.CurrentLoanRequest=existingLR",
        }),
      })
      .and({
        execute: () => true,
        description: "result=true",
      })
      .build().value;
    /*Postcondition End*/
  }
